import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("no")
        return

    n = int(data[0])
    m = int(data[1])

    if n == 0 or n == 1:
        print("no")
        return

    edges = []
    idx = 2
    for i in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        edges.append((u, v))
        idx += 2

    children = {}
    for u, v in edges:
        if u not in children:
            children[u] = []
        children[u].append(v)

    root = None
    all_nodes = set()

    child_set = set()
    for u, v in edges:
        child_set.add(v)

    for u, v in edges:
        all_nodes.add(u)
        all_nodes.add(v)

    for node in all_nodes:
        if node not in child_set:
            root = node
            break

    if root is None:
        print("no")
        return

    def build_tree(node):
        if node not in children or len(children[node]) == 0:
            return None

        child_list = sorted(children[node])
        left = child_list[0] if len(child_list) > 0 else None
        right = child_list[1] if len(child_list) > 1 else None

        left_sub = build_tree(left) if left else None
        right_sub = build_tree(right) if right else None

        return (left_sub, right_sub)

    def is_symmetric(tree):
        if tree is None:
            return True

        left, right = tree

        if left is None and right is None:
            return True

        if left is None or right is None:
            return False

        left_left, left_right = left
        right_left, right_right = right

        return is_symmetric((left_right, right_left)) and is_symmetric((left_left, right_right)) and \
               (left is not None and right is not None)

    tree = build_tree(root)

    if tree is None:
        print("no")
        return

    left, right = tree

    result = is_symmetric(tree)

    if result:
        print("yes")
    else:
        print("no")

if __name__ == "__main__":
    main()
